#!/usr/bin/env bash
# test-complexity-score.sh — unit tests for lib/complexity-score.sh, the
# deterministic half of ticket-appraise's complexity scoring (Step 2.5 sum,
# threshold and `## Complexity` block; Step 2.8 blast-radius write-back).
#
# Replay cases: the Step 2.5 rubric examples, the Blast Radius tables
# test-notes-parse.sh pins for get_blast_radius_override, and a fast-path
# notes.md generated by appraise-fast-path.sh. Each must reach the same
# simple/complex decision the prose rules give, read back by get_complexity.
#
# Usage: bash test-complexity-score.sh [test_name_filter]
set -eo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LIB_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
CS="$LIB_DIR/complexity-score.sh"

PASS=0
FAIL=0
FILTER="${1:-}"
TMP=""

_run() {
  local name="$1"
  shift
  [ -z "$FILTER" ] || [[ "$name" == *"$FILTER"* ]] || return 0
  TMP=$(mktemp -d)
  if "$@" 2>/dev/null; then
    echo "PASS: $name"
    ((PASS++)) || true
  else
    echo "FAIL: $name"
    ((FAIL++)) || true
  fi
  rm -rf "$TMP"
}

_setup_notes() {
  # ticket-setup's notes.md template (skills/ticket-setup/setup.sh).
  printf '# Working Notes — T-1\n\n## Status\n**Created:** 2026-11-12\n\n## Complexity\n\n**Score:**\n\n## Investigation Notes\n\n- Workspace created.\n' >"$TMP/notes.md"
}

_get() { bash -c 'source "$1/notes-parse.sh"; get_complexity "$2"' _ "$LIB_DIR" "$TMP"; }
_line() { grep "^\*\*$1:\*\* " "$TMP/notes.md" | head -1 | sed "s/^\*\*$1:\*\* //"; }

# write <axes> <expected-weighted> <expected-score>
_write_case() {
  _setup_notes
  local out
  out=$(bash "$CS" write "$TMP" --axes "$1" --reason "Because.") || return 1
  grep -qx "COMPLEXITY=$3" <<<"$out" && grep -qx "WEIGHTED=$2" <<<"$out" &&
    [ "$(_get)" = "$3" ] && [ "$(_line 'Weighted score')" = "$2 (threshold 3)" ]
}

# ── write: rubric replay ──────────────────────────────────────────────────────
test_none_is_simple() { _write_case none 0 simple && [ "$(_line 'Axes fired')" = "none" ]; }
test_one_weak_axis_simple() { _write_case multi-service 2 simple && [ "$(_line 'Axes fired')" = "multi-service:2" ]; }
test_two_weak_axes_complex() { _write_case "multi-service,cross-layer" 4 complex && [ "$(_line 'Axes fired')" = "multi-service:2, cross-layer:2" ]; }
test_reversibility_alone_complex() { _write_case "reversibility:schema-migration" 3 complex && [ "$(_line 'Axes fired')" = "reversibility:3 (schema-migration)" ]; }
test_framework_migration_marker() { _write_case "cross-layer:framework-migration" 3 complex && [ "$(_line 'Axes fired')" = "cross-layer (framework-migration):3" ]; }
test_prior_rejection_complex() { _write_case prior-rejection 3 complex; }
test_spaces_tolerated() { _write_case " multi-service , reversibility " 5 complex; }

test_block_shape_and_neighbours() {
  _setup_notes
  bash "$CS" write "$TMP" --axes multi-service --reason "Two services named." >/dev/null || return 1
  local want
  want=$(printf '## Complexity\n**Score:** simple\n**Weighted score:** 2 (threshold 3)\n**Axes fired:** multi-service:2\n**Reason:** Two services named.\n\n## Investigation Notes')
  grep -A6 '^## Complexity' "$TMP/notes.md" | grep -q 'Investigation Notes' &&
    [ "$(sed -n '/^## Complexity/,/^## Investigation Notes/p' "$TMP/notes.md")" = "$want" ] &&
    grep -q '^\*\*Created:\*\* 2026-11-12$' "$TMP/notes.md" && grep -q '^- Workspace created.$' "$TMP/notes.md"
}

test_rewrite_replaces_not_appends() {
  _setup_notes
  bash "$CS" write "$TMP" --axes multi-service --reason a >/dev/null &&
    bash "$CS" write "$TMP" --axes reversibility --reason b >/dev/null || return 1
  [ "$(grep -c '^## Complexity' "$TMP/notes.md")" -eq 1 ] && [ "$(_get)" = complex ] &&
    [ "$(grep -c '^\*\*Score:\*\*' "$TMP/notes.md")" -eq 1 ]
}

test_appends_when_section_absent() {
  printf '# Notes\n\n## Status\nx\n' >"$TMP/notes.md"
  bash "$CS" write "$TMP" --axes none --reason r >/dev/null && [ "$(_get)" = simple ]
}

# ── write: refusals ───────────────────────────────────────────────────────────
_refuses() {
  _setup_notes
  local before rc=0
  before=$(cat "$TMP/notes.md")
  bash "$CS" write "$TMP" --axes "$1" --reason r >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 2 ] && [ "$(cat "$TMP/notes.md")" = "$before" ]
}
test_unknown_axis_exit_2() { _refuses "multi-service,size"; }
test_cross_layer_migration_double_count_exit_2() { _refuses "reversibility,cross-layer:schema-migration"; }
test_duplicate_axis_exit_2() { _refuses "multi-service,multi-service"; }
test_none_with_other_axis_exit_2() { _refuses "none,multi-service"; }
test_qualifier_on_weak_axis_exit_2() { _refuses "multi-service:payments"; }
test_missing_notes_exit_12() {
  local rc=0
  bash "$CS" write "$TMP" --axes none --reason r >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 12 ]
}
test_missing_reason_exit_2() {
  _setup_notes
  local rc=0
  bash "$CS" write "$TMP" --axes none >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 2 ]
}

# ── blast ─────────────────────────────────────────────────────────────────────
_BR_HDR='## Blast Radius\n\n| Target | Risk | d=1 (WILL BREAK) | d=2 (LIKELY AFFECTED) | Affected Flows | Edit |\n|--------|------|-------------------|------------------------|----------------|------|\n'

# _scored <axes> <blast-rows>: a Step 2.5 block plus a Blast Radius table.
_scored() {
  _setup_notes
  bash "$CS" write "$TMP" --axes "$1" --reason "Base." >/dev/null || return 1
  printf "\n${_BR_HDR}%b" "$2" >>"$TMP/notes.md"
}

test_blast_escalates_simple() {
  _scored multi-service '| `a` | HIGH | 1 callers | 0 indirect | none | modifying |\n' || return 1
  local out
  out=$(bash "$CS" blast "$TMP") || return 1
  grep -qx 'COMPLEXITY=complex' <<<"$out" && [ "$(_get)" = complex ] &&
    [ "$(_line Score)" = "complex (escalated from simple — blast radius: risk HIGH (a))" ] &&
    [ "$(_line 'Weighted score')" = "5 (threshold 3)" ] &&
    [ "$(_line 'Axes fired')" = "multi-service:2, blast-radius:3" ] &&
    [ "$(_line Reason)" = "Base. Blast radius: risk HIGH (a)." ]
}

test_blast_is_idempotent() {
  _scored multi-service '| `a` | HIGH | 1 callers | 0 indirect | none | modifying |\n' || return 1
  bash "$CS" blast "$TMP" >/dev/null || return 1
  local once
  once=$(cat "$TMP/notes.md")
  bash "$CS" blast "$TMP" >/dev/null && [ "$(cat "$TMP/notes.md")" = "$once" ]
}

test_blast_keeps_complex_score_line() {
  _scored reversibility:auth-rule '| `a` | LOW | 5 callers | 0 indirect | none | modifying |\n' || return 1
  bash "$CS" blast "$TMP" >/dev/null && [ "$(_line Score)" = complex ] &&
    [ "$(_line 'Weighted score')" = "6 (threshold 3)" ]
}

test_blast_none_leaves_file_untouched() {
  _scored multi-service '| `a` | MEDIUM | 2 callers | 9 indirect | Login | modifying |\n' || return 1
  local before
  before=$(cat "$TMP/notes.md")
  bash "$CS" blast "$TMP" >/dev/null && [ "$(cat "$TMP/notes.md")" = "$before" ] && [ "$(_get)" = simple ]
}

test_blast_additive_skip_records_line_only() {
  _scored multi-service '| `can()` | LOW | 23 callers | 4 indirect | none | additive |\n' || return 1
  bash "$CS" blast "$TMP" >/dev/null && bash "$CS" blast "$TMP" >/dev/null || return 1
  [ "$(_get)" = simple ] && [ "$(_line 'Weighted score')" = "2 (threshold 3)" ] &&
    [ "$(grep -c '^\*\*blast-radius:\*\* additive — caller-count override skipped (can() (23 callers))$' "$TMP/notes.md")" -eq 1 ]
}

test_blast_section_absent_is_noop() {
  _setup_notes
  bash "$CS" write "$TMP" --axes none --reason r >/dev/null || return 1
  local before out
  before=$(cat "$TMP/notes.md")
  out=$(bash "$CS" blast "$TMP") && grep -qx 'BLAST_OVERRIDE=none' <<<"$out" &&
    [ "$(cat "$TMP/notes.md")" = "$before" ]
}

test_blast_parser_contract_survives() {
  _scored none '| `a` | LOW | 4 callers | 0 indirect | A, B | modifying |\n' || return 1
  bash "$CS" blast "$TMP" >/dev/null || return 1
  local out
  out=$(bash -c 'source "$1/notes-parse.sh"; get_blast_radius_override "$2"' _ "$LIB_DIR" "$TMP") &&
    grep -q '^BLAST_OVERRIDE=complex$' <<<"$out" && [ "$(_line 'Weighted score')" = "3 (threshold 3)" ] &&
    [ "$(_line 'Axes fired')" = "none, blast-radius:3" ]
}

# Replay the get_blast_radius_override cases test-notes-parse.sh pins:
# rows -> decision for a `multi-service` (simple, 2) ticket.
test_blast_replay_notes_parse_cases() {
  local rows want
  while IFS='#' read -r rows want; do
    _scored multi-service "$rows" || return 1
    bash "$CS" blast "$TMP" >/dev/null || return 1
    [ "$(_get)" = "$want" ] || return 1
    rm -f "$TMP/notes.md"
  done <<'EOF'
| `can()` | LOW | 23 callers | 4 indirect | none | additive |\n#simple
| `can()` | LOW | 23 callers | 4 indirect | none | modifying |\n#complex
| `can()` | MEDIUM | 23 callers | 4 indirect | none |\n#complex
| `a` | HIGH | 23 callers | 0 indirect | none | additive |\n#complex
| `a` | LOW | 23 callers | 0 indirect | Login, Logout | additive |\n#complex
| `a` | MEDIUM | 2 callers | 9 indirect | Login | modifying |\n#simple
| `it's; $(touch /nonexistent-413)` | CRITICAL | 0 callers | 0 indirect | none | modifying |\n#complex
EOF
  [ ! -e /nonexistent-413 ]
}

# A fast-path notes.md (Conservative strategy, no keyword) carries
# `**Weighted score:** n/a (...)`; blast writes `3 (threshold 3)`.
test_blast_fast_path_na_line() {
  bash -c '
    source "$1/appraise-fast-path.sh"
    FAST_PATH_STRATEGY=Conservative FAST_PATH_DESCRIPTION="Rename a label" generate_fast_path_notes "$2" T-1
  ' _ "$LIB_DIR" "$TMP" || return 1
  [ "$(_get)" = simple ] || return 1
  printf "\n${_BR_HDR}%b" '| `a` | CRITICAL | 0 callers | 0 indirect | none | modifying |\n' >>"$TMP/notes.md"
  bash "$CS" blast "$TMP" >/dev/null || return 1
  [ "$(_get)" = complex ] && [ "$(_line 'Weighted score')" = "3 (threshold 3)" ] &&
    grep -q '^## Prior Art$' "$TMP/notes.md" &&
    [ "$(_line 'Axes fired')" = "none (fast-path — planner-provided; reversibility keyword scan: no match), blast-radius:3" ]
}

test_usage_exit_2() {
  local rc=0
  bash "$CS" bogus "$TMP" >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 2 ]
}

for fn in $(declare -F | awk '$3 ~ /^test_/ {print $3}'); do
  _run "$fn" "$fn"
done

echo ""
echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]
